  "After the battery change{0} on {1} the lock raised a battery alarm (first: {2}, {3}) while its readings stayed above {4} V. A battery alarm after new batteries, even once, is a firmware fault, not a battery problem; it is not counted as a battery alarm here.": "Après le changement de piles{0} du {1}, la serrure a déclenché une alarme de piles (première : {2}, {3}) alors que ses relevés restaient au-dessus de {4} V. Une alarme de piles après des piles neuves, même une seule fois, est un défaut du micrologiciel, pas un problème de piles ; elle n'est pas comptée ici comme alarme de piles.",
  "After the work, read the lock again in 3 weeks or more and upload its report: the portal compares the battery use before and after, and says whether this part was the cause.": "Après les travaux, relisez la serrure dans 3 semaines ou plus et chargez son relevé : le portail compare la consommation des piles avant et après, et dit si cette pièce était la cause.",
