  "By user group: {0}. A staff keycard is counted on the day it first appeared in Visionline's card list or live feed.": "Par groupe d'utilisateurs : {0}. Un badge du personnel est compté le jour où il est apparu pour la première fois dans la liste des badges de Visionline ou le flux en direct.",
  "CSV opens in Excel and imports into most payroll systems (one row per person per day, or one row per person). JSON is for a payroll system that reads it directly. The PDF has your header on every page and can be checked later (Event log → Verify a PDF).": "Le CSV s'ouvre dans Excel et s'importe dans la plupart des systèmes de paie (une ligne par personne et par jour, ou une ligne par personne). Le JSON est pour un système de paie qui le lit directement. Le PDF porte votre en-tête sur chaque page et peut être vérifié plus tard (Journal des événements → Vérifier un PDF).",
  "Call the duty manager if a door will not open.": "Appelez le responsable de service si une porte ne s'ouvre pas.",
