  "Changes are paused until a licence key is entered. Keys can still be revoked, reports read and people signed in; doors in Visionline are not affected.": "Les modifications sont suspendues jusqu'à la saisie d'une clé de licence. Les clés peuvent toujours être révoquées, les rapports lus et les personnes se connecter ; les portes dans Visionline ne sont pas affectées.",
  "Channel": "Canal",
  "Chart": "Graphique",
  "Check": "Vérifier",
  "Check each point on the door, simplest first, and mark it. What the report shows is given for each; a firmware fault can also drain batteries, so rule out the other causes before blaming the batteries.": "Vérifiez chaque point sur la porte, le plus simple d'abord, et cochez-le. Ce que montre le relevé est indiqué pour chacun ; un défaut du micrologiciel peut aussi user les piles, donc écartez les autres causes avant d'accuser les piles.",
  "Check failed": "La vérification a échoué",
  "Check file": "Vérifier le fichier",
  "Check in": "Pointer l'arrivée",
  "Check integrity": "Vérifier l'intégrité",
  "Check now": "Vérifier maintenant",
  "Check on site": "À vérifier sur place",
  "Check out": "Pointer le départ",
  "Check staff in and out, see timesheets, record leave and send the hours to payroll. Keycard holders are clocked by the attendance doors; people without a card (daily workers) are checked in at the desk or entered by HR.": "Pointez les arrivées et départs du personnel, consultez les feuilles de temps, enregistrez les congés et envoyez les heures à la paie. Les titulaires de badge sont pointés par les portes de présence ; les personnes sans badge (journaliers) sont pointées à l'accueil ou saisies par les RH.",
  "Check that the batteries are new, of the type the lock requires (alkaline or lithium as specified, not rechargeable), all from the same pack, and that the contacts are clean and tight. Then look at the lock and door findings below: a lock that restarts, keeps its motor running, or a door that rubs or is left open, drains batteries.": "Vérifiez que les piles sont neuves, du type exigé par la serrure (alcalines ou lithium selon la spécification, pas rechargeables), toutes du même paquet, et que les contacts sont propres et serrés. Regardez ensuite les constats sur la serrure et la porte ci-dessous : une serrure qui redémarre, un moteur qui tourne sans cesse, ou une porte qui frotte ou reste ouverte, use les piles.",
  "Check that the latch and strike engage every time the door closes (door alignment, closer speed). If the door was latched, treat it as a security incident.": "Vérifiez que le pêne et la gâche s'engagent à chaque fermeture (alignement de la porte, vitesse du ferme-porte). Si la porte était verrouillée, traitez-le comme un incident de sécurité.",
  "Check that the newest events below are right; switch if day and month are swapped.": "Vérifiez que les événements les plus récents ci-dessous sont justes ; inversez si le jour et le mois sont permutés.",
  "Check the battery holder, its springs and contacts, and the cable to the door unit.": "Vérifiez le porte-piles, ses ressorts et contacts, et le câble vers la serrure.",
  "Check the cards and user groups of the people concerned (expired cards, missing rights, deadbolt override for staff who must enter). Repeated refusals also use battery.": "Vérifiez les badges et groupes d'utilisateurs des personnes concernées (badges expirés, droits manquants, passe-outre du verrou pour le personnel qui doit entrer). Des refus répétés consomment aussi des piles.",
  "Check the door closer and that the door shuts and latches by itself; check that it is not wedged open.": "Vérifiez le ferme-porte et que la porte se ferme et s'enclenche d'elle-même ; vérifiez qu'elle n'est pas calée ouverte.",
  "Check the firmware version of the lock (service device: read lock information) and of Visionline/the service device; ask ASSA ABLOY whether the version is known to drain batteries on this lock model.": "Vérifiez la version du micrologiciel de la serrure (appareil de service : lire les informations de la serrure) et de Visionline/de l'appareil de service ; demandez à ASSA ABLOY si cette version est connue pour user les piles sur ce modèle de serrure.",
  "Check the lock's BLE module and firmware.": "Vérifiez le module BLE et le micrologiciel de la serrure.",
  "Check who holds the metal key and why it was used; if the lock had no power, look at the battery findings.": "Vérifiez qui détient la clé mécanique et pourquoi elle a été utilisée ; si la serrure n'avait plus d'alimentation, regardez les constats sur les piles.",
  "Check with ASSA ABLOY that the keycard model (MIFARE / VingCard) is printable: some are glossy and need a printable PVC surface.": "Vérifiez auprès d'ASSA ABLOY que le modèle de badge (MIFARE / VingCard) est imprimable : certains sont brillants et nécessitent une surface PVC imprimable.",
  "Check-in desk, timesheets, leave, payroll exports. Door entrances count when attendance doors are set (Time & attendance -> Setup).": "Accueil de pointage, feuilles de temps, congés, exports de paie. Les entrées aux portes comptent quand les portes de présence sont définies (Pointage -> Configuration).",
  "Check:": "Vérifier :",
