  "Checkout to online locks, clearance card for offline ones": "Départ vers les serrures en ligne, badge de libération pour les hors ligne",
  "Checks the key out of each of its doors (Web API §7.13.5). The key leaves the phone when all are checked out.": "Fait le départ de la clé pour chacune de ses portes (API Web §7.13.5). La clé quitte le téléphone quand toutes sont faites.",
  "Children": "Enfants",
  "Children count as breakfast guests": "Les enfants comptent comme clients du petit-déjeuner",
  "Choose a PDF printed from this platform. Your browser computes its fingerprint (SHA-256) and the platform checks it against the PDFs it printed. Any change to the file, even one character, makes the check fail. The file itself is not uploaded.": "Choisissez un PDF imprimé par cette plateforme. Votre navigateur calcule son empreinte (SHA-256) et la plateforme la compare aux PDF qu'elle a imprimés. Toute modification du fichier, même d'un seul caractère, fait échouer la vérification. Le fichier lui-même n'est pas envoyé.",
  "Choose a day (YYYY-MM-DD) or a month (YYYY-MM).": "Choisissez un jour (AAAA-MM-JJ) ou un mois (AAAA-MM).",
  "Choose a door…": "Choisir une porte…",
