  "Choose e-mail, SMS or both.": "Choisissez e-mail, SMS ou les deux.",
  "Choose file…": "Choisir un fichier…",
  "Choose one of the encoders (Staff keycards → Encoders & special cards).": "Choisissez l'un des encodeurs (Badges du personnel → Encodeurs et badges spéciaux).",
  "Choose one of the encoders chosen in Settings -> Keycards.": "Choisissez l'un des encodeurs retenus dans Paramètres -> Badges.",
  "Choose roles instead": "Choisir plutôt des rôles",
  "Choose the Email column and a name column (Full name, or First and Last name).": "Choisissez la colonne E-mail et une colonne de nom (Nom complet, ou Prénom et Nom).",
