  "Classic serif": "Serif classique",
  "Clean the reader; if it continues for different cards, check the reader. Replace damaged cards.": "Nettoyez le lecteur ; si cela continue avec différents badges, vérifiez le lecteur. Remplacez les badges abîmés.",
