  "Closed as settled. Issue a new key in Opera.": "Clôturé comme réglé. Délivrez une nouvelle clé dans Opera.",
  "Closes when the alarm is completed in Visionline (Alarms), or 24 hours after it was raised.": "Se ferme quand l'alarme est terminée dans Visionline (Alarmes), ou 24 heures après son déclenchement.",
  "Closes when the batteries are changed (Battery status → New batteries) or the lock reports a good battery.": "Se ferme quand les piles sont changées (État des piles → Piles neuves) ou que la serrure signale des piles correctes.",
  "Closes when the connector on the Visionline server reports again (check that its service runs).": "Se ferme quand le connecteur du serveur Visionline transmet de nouveau (vérifiez que son service fonctionne).",
  "Closes when the connector reaches Visionline again.": "Se ferme quand le connecteur joint de nouveau Visionline.",
  "Closes when the database is below the limit, or after raising the limit in Settings → Alerts & notifications.": "Se ferme quand la base de données est sous la limite, ou après avoir relevé la limite dans Paramètres → Alertes et notifications.",
  "Closes when the disk has more free space than the limit (Settings → Alerts & notifications).": "Se ferme quand le disque a plus d'espace libre que la limite (Paramètres → Alertes et notifications).",
  "Closes when the door reports again (a keycard used there, or the lock back in contact). Door-silence alerts can be switched off in Settings → Alerts & notifications.": "Se ferme quand la porte transmet de nouveau (un badge utilisé à cette porte, ou la serrure de nouveau en contact). Les alertes de porte silencieuse peuvent être désactivées dans Paramètres → Alertes et notifications.",
  "Closes when the gateway is online again.": "Se ferme quand la passerelle est de nouveau en ligne.",
  "Closes when those keycards are put in a person's name or cancelled (Staff keycards → Renewals & duplicates).": "Se ferme quand ces badges sont mis au nom d'une personne ou annulés (Badges du personnel → Renouvellements et doublons).",
