  "Doors that count as broad access": "Portes qui comptent comme accès large",
  "Doors that lose contact, watched (VIP) doors, lock alarms, and the health of the server, database and connector. Alerts go by e-mail and SMS to the people set in Settings → Alerts & notifications.": "Les portes qui perdent le contact, les portes surveillées (VIP), les alarmes de serrure, et la santé du serveur, de la base de données et du connecteur. Les alertes partent par e-mail et SMS aux personnes définies dans Paramètres → Alertes et notifications.",
  "Doors, user groups and accounts discovered": "Portes, groupes d'utilisateurs et comptes découverts",
  "Doors, user groups, people and keycards are read only when someone presses \"Refresh from Visionline\" (for example after lock data was uploaded to Visionline or its resources were refreshed), at most once every 5 minutes. Visionline is not loaded with regular reads. Cards used at doors and battery reports still arrive as they happen.": "Les portes, groupes d'utilisateurs, personnes et badges ne sont lus que lorsque quelqu'un clique sur « Actualiser depuis Visionline » (par exemple après le chargement des données des serrures dans Visionline ou l'actualisation de ses ressources), au plus une fois toutes les 5 minutes. Visionline n'est pas chargé par des lectures régulières. Les badges utilisés aux portes et les relevés de piles arrivent toujours au fil de l'eau.",
