  "EEID: letters, digits and : . _ - only": "EEID : lettres, chiffres et : . _ - uniquement",
  "Each operator adds them under Your account → Visionline credentials. Keys are then recorded in Visionline under that operator’s name.": "Chaque opérateur les ajoute dans Votre compte → Identifiants Visionline. Les clés sont alors enregistrées dans Visionline au nom de cet opérateur.",
  "Each person chooses e-mail, SMS or both, and which kinds of alert. Save the e-mail/SMS settings above first, then send a test.": "Chaque personne choisit e-mail, SMS ou les deux, et les types d'alerte. Enregistrez d'abord les réglages e-mail/SMS ci-dessus, puis envoyez un test.",
  "Each save creates a new version you can roll back to.": "Chaque enregistrement crée une nouvelle version vers laquelle vous pouvez revenir.",
  "Each set from one battery change to the next, with what was changed when it was fitted. If the sets keep lasting the same after a part was changed, that part was not the cause.": "Chaque jeu, d'un changement de piles au suivant, avec ce qui a été changé à la pose. Si les jeux durent toujours autant après le changement d'une pièce, cette pièce n'était pas la cause.",
