  "Enter the Visionline card number to cancel (Card lookup shows it).": "Saisissez le numéro de badge Visionline à annuler (Recherche de badge l'affiche).",
  "Enter the code from your authenticator app as well.": "Saisissez aussi le code de votre application d'authentification.",
  "Enter them under Settings → Visionline (or on the connector page)": "Saisissez-les dans Paramètres → Visionline (ou sur la page du connecteur)",
  "Enter your organisation's details and create the first administrator. Everything here can be changed later in the portal, except the short code.": "Saisissez les coordonnées de votre organisation et créez le premier administrateur. Tout peut être modifié plus tard dans le portail, sauf le code court.",
  "Enter your personal Visionline password": "Saisissez votre mot de passe Visionline personnel",
