  "Entrance": "Entrée",
  "Entrance event codes": "Codes d'événement d'entrée",
  "Entrance events": "Événements d'entrée",
  "Entrances and refused entries appear here as the locks report them.": "Les entrées et les entrées refusées apparaissent ici au fur et à mesure que les serrures les transmettent.",
  "Entrances and refused entries per door.": "Entrées et entrées refusées par porte.",
  "Entrances appear as the locks report them.": "Les entrées apparaissent au fur et à mesure que les serrures les transmettent.",
  "Entrances at these doors count as clock records for the person whose keycard or mobile key opened them: the first of the day is the arrival, the last the departure. Usually the staff entrance. Door entrances need the connector's Visionline watch with entrance recording on (Settings → Event log).": "Les entrées à ces portes comptent comme pointages pour la personne dont le badge ou la clé mobile les a ouvertes : la première de la journée est l'arrivée, la dernière le départ. En général l'entrée du personnel. Les entrées aux portes nécessitent la surveillance Visionline du connecteur avec l'enregistrement des entrées activé (Paramètres → Journal des événements).",
  "Entrances by hour of the day": "Entrées par heure de la journée",
  "Entrances come from the locks through the connector's Visionline watch (entrance codes in Settings → Event log).": "Les entrées viennent des serrures par la surveillance Visionline du connecteur (codes d'entrée dans Paramètres → Journal des événements).",
  "Entrances, refused entries and other lock events reported by Visionline.": "Entrées, entrées refusées et autres événements de serrure signalés par Visionline.",
  "Entrances, refused entries, alarms read from Visionline. Access history and the event log go back this far.": "Entrées, entrées refusées, alarmes lues dans Visionline. L'historique des accès et le journal des événements remontent jusque-là.",
