  "Even a single alarm. No battery alarm is raised and no battery is asked for, unless a voltage reading since the change confirms low batteries. A high-priority request is opened. 0 = off.": "Même une seule alarme. Aucune alarme de piles n'est déclenchée et aucune pile n'est demandée, sauf si un relevé de tension depuis le changement confirme des piles faibles. Une demande de priorité haute est ouverte. 0 = désactivé.",
