  "Every Visionline user, whatever the group.": "Chaque utilisateur Visionline, quel que soit son groupe.",
  "Every change here is a new version in the audit trail.": "Chaque modification ici est une nouvelle version dans la piste d'audit.",
  "Every door, keycard and lock at": "Chaque porte, badge et serrure de",
  "Every door, keycard and lock at {0}.": "Chaque porte, badge et serrure de {0}.",
  "Every entrance": "Chaque entrée",
  "Every key has a start and an end. The Web API says a staff card’s start time should not be in the future (§7.6.2), so by default the platform waits and creates the key at its start time. Choose the second option only once ASSA ABLOY confirms future start times for staff mobile keys.": "Chaque clé a un début et une fin. L'API Web indique que l'heure de début d'un badge du personnel ne devrait pas être dans le futur (§7.6.2) : par défaut, la plateforme attend et crée la clé à son heure de début. Ne choisissez la deuxième option qu'une fois qu'ASSA ABLOY a confirmé les heures de début futures pour les clés mobiles du personnel.",
  "Every lock with a history: state, battery changes, last set, last work.": "Chaque serrure avec un historique : état, changements de piles, dernier jeu, derniers travaux.",
  "Every online door": "Toutes les portes en ligne",
  "Every privileged action, in order. Records are chained by hash, so any edit or deletion is detectable.": "Chaque action privilégiée, dans l'ordre. Les enregistrements sont chaînés par empreinte : toute modification ou suppression est détectable.",
  "Every staff key, from request to expiry. Open a key to see its doors and history.": "Chaque clé du personnel, de la demande à l'expiration. Ouvrez une clé pour voir ses portes et son historique.",
