  "How alerts reach people. The mail server password and the SMS key are entered under Passwords and keys below: stored encrypted on the server and never shown again.": "Comment les alertes parviennent aux personnes. Le mot de passe du serveur de messagerie et la clé SMS sont saisis ci-dessous dans Mots de passe et clés : stockés chiffrés sur le serveur et jamais réaffichés.",
  "How battery alarms and maintenance requests are handled. Part of the policy; each save is a new policy version.": "Comment les alarmes de piles et les demandes de maintenance sont traitées. Fait partie des règles ; chaque enregistrement est une nouvelle version des règles.",
  "How it ended": "Comment elle a pris fin",
  "How it works": "Fonctionnement",
  "How keys are created in Visionline. These settings mirror Visionline Options so the platform and the app behave the same way as the lock system.": "Comment les clés sont créées dans Visionline. Ces réglages reprennent les options de Visionline pour que la plateforme et l'application se comportent comme le système de serrures.",
