  "How long each set of batteries lasted": "Durée de chaque jeu de piles",
  "How long personal data is kept. Older data is deleted automatically every hour, a little at a time. The audit trail is always kept.": "Durée de conservation des données personnelles. Les données plus anciennes sont supprimées automatiquement toutes les heures, un peu à la fois. La piste d'audit est toujours conservée.",
  "How long sets of batteries lasted, by the year they were fitted, over all the locks with a history. A drop on many locks at once points to a common cause: battery supply, a setting, firmware.": "Durée des jeux de piles, selon l'année où ils ont été posés, sur toutes les serrures avec un historique. Une baisse sur beaucoup de serrures à la fois indique une cause commune : approvisionnement en piles, un réglage, le micrologiciel.",
  "How many cards": "Nombre de badges",
  "How the platform handles each point, from the Visionline Web API manual; check them once on your own Visionline.": "Comment la plateforme traite chaque point, d'après le manuel de l'API Web Visionline ; à vérifier une fois sur votre propre Visionline.",
