  "Is the door aligned; do latch and strike engage without rubbing; does the closer shut and latch the door; does the deadbolt turn freely?": "La porte est-elle alignée ; le pêne et la gâche s'engagent-ils sans frotter ; le ferme-porte ferme-t-il et enclenche-t-il la porte ; le verrou tourne-t-il librement ?",
  "Is the lock outdoors, in a humid or very cold or hot place (pool, kitchen, near heating, direct sun)? Batteries lose capacity there.": "La serrure est-elle à l'extérieur, dans un endroit humide, très froid ou très chaud (piscine, cuisine, près d'un chauffage, plein soleil) ? Les piles y perdent de la capacité.",
