  "Locks record entries, not exits: check every room and area, this list is a starting point.": "Les serrures enregistrent les entrées, pas les sorties : vérifiez chaque chambre et chaque zone, cette liste est un point de départ.",
  "Locks record who opens a door, not who leaves: people count as on site for": "Les serrures enregistrent qui ouvre une porte, pas qui part : les personnes comptent comme sur place pendant",
  "Locks record who opens a door, not who leaves: people count as on site for {0} hours after their last door (or until they check out at attendance), rooms count as used for {1} hours after the door was opened. Treat this as the starting point of a sweep, not as proof that an area is empty. Offline locks report their entries later. {2}": "Les serrures enregistrent qui ouvre une porte, pas qui part : les personnes comptent comme sur place pendant {0} heures après leur dernière porte (ou jusqu'à leur départ pointé), les chambres comptent comme utilisées pendant {1} heures après l'ouverture de la porte. Considérez cela comme le point de départ d'une ronde, pas comme la preuve qu'une zone est vide. Les serrures hors ligne transmettent leurs entrées plus tard. {2}",
  "Locks report only when their events reach Visionline.": "Les serrures ne transmettent que lorsque leurs événements atteignent Visionline.",
  "Locks with a critical battery now": "Serrures avec des piles critiques maintenant",
  "Locks with no alarm, no change and a good battery are left out ({0} locks).": "Les serrures sans alarme, sans changement et avec de bonnes piles sont omises ({0} serrures).",
