  "One person starts it, a second person confirms it; both re-enter their password. Use a drill to practise the roll call: no keys are issued during a drill.": "Une personne la déclenche, une deuxième la confirme ; les deux ressaisissent leur mot de passe. Utilisez un exercice pour vous entraîner à l'appel : aucune clé n'est délivrée pendant un exercice.",
