  "Online locks": "Serrures en ligne",
  "Online locks get the emergency open command from Visionline; offline locks need the emergency card (encode one in Staff keycards -> Encoders & special cards).": "Les serrures en ligne reçoivent la commande d'ouverture d'urgence de Visionline ; les serrures hors ligne nécessitent le badge d'urgence (encodez-en un dans Badges du personnel -> Encodeurs et badges spéciaux).",
  "Online locks keep a radio link to their gateway: is the signal to the gateway good, and the gateway online? A weak link makes the lock retry and use more battery.": "Les serrures en ligne gardent une liaison radio avec leur passerelle : le signal vers la passerelle est-il bon, et la passerelle en ligne ? Une liaison faible fait réessayer la serrure et consomme plus de piles.",
