  "Program the lock and upload its firmware. If the error continues, have the door unit (electronics) checked or replaced.": "Programmez la serrure et chargez son micrologiciel. Si l'erreur persiste, faites vérifier ou remplacer l'électronique de la serrure.",
  "Program the lock and upload the firmware with the service tool; read the lock again afterwards. Firmware faults cause false battery alarms and can also drain the batteries.": "Programmez la serrure et chargez le micrologiciel avec l'outil de service ; relisez ensuite la serrure. Les défauts du micrologiciel provoquent de fausses alarmes de piles et peuvent aussi user les piles.",
