  "Start with the quick start; the full manual explains every page. Print either (Save as PDF) for the team.": "Commencez par le démarrage rapide ; le manuel complet explique chaque page. Imprimez l'un ou l'autre (Enregistrer en PDF) pour l'équipe.",
