  "Template “{0}”, valid {1} hours. The two-person confirmation counts as the approval for broad access. Only staff whose phone is set up are listed.": "Modèle « {0} », valable {1} heures. La confirmation à deux personnes vaut approbation de l'accès large. Seul le personnel dont le téléphone est configuré est listé.",
