  "Two-step sign-in is on. You’ll be asked for a code from your authenticator app each time you sign in.": "La connexion en deux étapes est activée. Un code de votre application d'authentification vous sera demandé à chaque connexion.",
  "Two-step sign-in is required for administrators here. Turn it on in Your account -> Two-step sign-in, then sign in again.": "La connexion en deux étapes est obligatoire pour les administrateurs ici. Activez-la dans Votre compte -> Connexion en deux étapes, puis reconnectez-vous.",
