  "Typed here once, stored encrypted on this server and never shown again, not even to administrators. To change one, enter the new value.": "Saisis ici une fois, stockés chiffrés sur ce serveur et jamais réaffichés, pas même aux administrateurs. Pour en changer un, saisissez la nouvelle valeur.",
