  "Visionline keycard holder": "Titulaire de badge Visionline",
  "Visionline lock event numbers, separated by commas. 64 = staff card accepted (Web API §7.14.1). Add the codes for other accepted cards from your lock documentation.": "Numéros d'événement de serrure Visionline, séparés par des virgules. 64 = badge du personnel accepté (API Web §7.14.1). Ajoutez les codes des autres badges acceptés d'après la documentation de vos serrures.",
  "Visionline lock events 320 “No access to this room” and 323 “Common rooms only”, reported by the connector. 0 switches it off. Usual value: 5.": "Événements de serrure Visionline 320 « Pas d'accès à cette chambre » et 323 « Parties communes uniquement », signalés par le connecteur. 0 désactive. Valeur habituelle : 5.",
  "Visionline logs every keycard made from the portal under \"": "Visionline enregistre chaque badge créé depuis le portail sous « ",
  "Visionline logs every keycard made from the portal under \"{0}\". Give each person a named Visionline operator.": "Visionline enregistre chaque badge créé depuis le portail sous « {0} ». Donnez à chaque personne un opérateur Visionline nominatif.",
  "Visionline makes AES keycards. Next: make the \"Disable legacy key mode\" card and show it to every lock.": "Visionline crée des badges AES. Prochaine étape : créer le badge « Désactiver le mode de clé ancien » et le présenter à chaque serrure.",
  "Visionline makes AES keycards; the \"Disable legacy key mode\" card has been made (locks stop accepting old cards once it is shown to each).": "Visionline crée des badges AES ; le badge « Désactiver le mode de clé ancien » a été créé (les serrures n'acceptent plus les anciens badges dès qu'il leur est présenté).",
  "Visionline marks a door as online when it is run by the online system. Run discovery (Settings → Connector) to read the doors.": "Visionline marque une porte comme en ligne quand elle est gérée par le système en ligne. Lancez la découverte (Paramètres → Connecteur) pour lire les portes.",
  "Visionline mobile access (TLCode) option is not enabled (40328). Contact ASSA ABLOY.": "L'option d'accès mobile Visionline (TLCode) n'est pas activée (40328). Contactez ASSA ABLOY.",
  "Visionline only": "Visionline uniquement",
  "Visionline only (cards, people, access history, event log, reports)": "Visionline uniquement (badges, personnes, historique des accès, journal des événements, rapports)",
  "Visionline only hides mobile keys, attendance, breakfast, battery and maintenance from everyone except administrators. Nothing is deleted. Each person can also tidy their own menu (Your account -> Menu & appearance).": "Visionline uniquement masque les clés mobiles, le pointage, le petit-déjeuner, les piles et la maintenance à tous sauf aux administrateurs. Rien n'est supprimé. Chacun peut aussi ranger son propre menu (Votre compte -> Menu et apparence).",
  "Visionline only: version, AES key mode, locks, user groups, operators and system parameters.": "Visionline uniquement : version, mode de clé AES, serrures, groupes d'utilisateurs, opérateurs et paramètres système.",
