  "Visionline records every keycard made from this portal under that name, so its own card log cannot say who made it. Change it or add operators: give each person their own Visionline operator and let them store it under": "Visionline enregistre chaque badge créé depuis ce portail sous ce nom : son propre journal des badges ne peut donc pas dire qui l'a créé. Modifiez-le ou ajoutez des opérateurs : donnez à chaque personne son propre opérateur Visionline et laissez-la l'enregistrer dans",
