  "Voltage thresholds, for locks that send “Battery level below X volts” events (Visionline events 1056–1081). Leave empty to show the reading without raising alarms. Take the values from your lock models’ documentation.": "Seuils de tension, pour les serrures qui envoient des événements « Niveau des piles inférieur à X volts » (événements Visionline 1056–1081). Laissez vide pour afficher le relevé sans déclencher d'alarme. Prenez les valeurs dans la documentation de vos modèles de serrure.",
