  "When the lock firmware was upgraded, and how long battery sets lasted before and after, over the locks concerned. A big drop after an upgrade points to the firmware.": "Quand le micrologiciel des serrures a été mis à jour, et combien de temps les jeux de piles ont duré avant et après, sur les serrures concernées. Une forte baisse après une mise à jour désigne le micrologiciel.",
  "When to read Visionline": "Quand lire Visionline",
  "Where": "Où",
  "Where does the connector run?": "Où fonctionne le connecteur ?",
  "Where the connector runs: on this server, or on another computer of the network. For another computer this page writes the commands with your addresses filled in.": "Où fonctionne le connecteur : sur ce serveur, ou sur un autre ordinateur du réseau. Pour un autre ordinateur, cette page écrit les commandes avec vos adresses déjà remplies.",
  "Which days alarms happen.": "Les jours où les alarmes se produisent.",
  "Which door is this lock?": "Quelle porte est cette serrure ?",
  "Which doors a person opened or was refused at, and who went through a door. From the lock events Visionline reports (offline locks report when they reconnect).": "Les portes qu'une personne a ouvertes ou où elle a été refusée, et qui est passé par une porte. D'après les événements de serrure transmis par Visionline (les serrures hors ligne transmettent quand elles se reconnectent).",
  "Which doors reported recently and which are silent.": "Quelles portes ont transmis récemment et lesquelles sont silencieuses.",
  "Which keycards opened each room or were refused, whose they are and who issued them. Offline locks appear once their events are uploaded to Visionline, at the time the lock recorded them.": "Quels badges ont ouvert chaque chambre ou ont été refusés, à qui ils sont et qui les a délivrés. Les serrures hors ligne apparaissent dès que leurs événements sont chargés dans Visionline, à l'heure enregistrée par la serrure.",
  "Which lock events the connector records for the Event log. Refused entries and battery events are always recorded. Part of the policy; each save is a new policy version.": "Quels événements de serrure le connecteur enregistre pour le Journal des événements. Les entrées refusées et les événements de piles sont toujours enregistrés. Fait partie des règles ; chaque enregistrement est une nouvelle version des règles.",
  "Which lock model?": "Quel modèle de serrure ?",
  "Which portal user each Visionline operator is, so a keycard made in Visionline shows who issued it.": "Quel utilisateur du portail est chaque opérateur Visionline, pour qu'un badge créé dans Visionline indique qui l'a délivré.",
  "While a lock still drains, follow the next part to check": "Tant qu'une serrure use encore ses piles, suivez la prochaine pièce à vérifier",
