  "Wrong type (not industrial alkaline), old stock, mixed packs or fitted the wrong way drain fast or give false alarms. Fit a new pack of industrial alkaline AA from a known supplier, note the brand and batch, and check each cell with a multimeter before fitting (about 1.6 V for a fresh alkaline cell).": "Un mauvais type (pas alcaline industrielle), un stock ancien, des paquets mélangés ou des piles posées à l'envers s'usent vite ou donnent de fausses alarmes. Posez un paquet neuf de piles AA alcalines industrielles d'un fournisseur connu, notez la marque et le lot, et vérifiez chaque pile au multimètre avant de la poser (environ 1,6 V pour une pile alcaline neuve).",
