  "held under a name that is not a person (\"Staff\", \"HK 2\", \"Spare\", a number…). Nobody can tell who used": "au nom de quelque chose qui n'est pas une personne (« Personnel », « HK 2 », « Réserve », un numéro…). Personne ne peut savoir qui a utilisé",
