  "hours after the door was opened. Treat this as the starting point of a sweep, not as proof that an area is empty. Offline locks report their entries later.": "heures après l'ouverture de la porte. Considérez cela comme le point de départ d'une ronde, pas comme la preuve qu'une zone est vide. Les serrures hors ligne transmettent leurs entrées plus tard.",
