  "The connector is not registered on this server yet. Restart the server: the installer registers it when its services start.": "Le connecteur n'est pas encore enregistré sur ce serveur. Redémarrez le serveur : l'installateur l'enregistre au démarrage de ses services.",
  "The connector on this server is not running. Check that the \"Access Monitoring Tool\" services are started.": "Le connecteur de ce serveur ne fonctionne pas. Vérifiez que les services « Access Monitoring Tool » sont démarrés.",
  "Enter the Visionline account the portal reads with (a Visionline user with read rights). This is the only setting.": "Saisissez le compte Visionline avec lequel le portail lit les données (un utilisateur Visionline avec droits de lecture). C'est le seul réglage.",
  "The connector cannot reach Visionline with this account. Check that Visionline is running, then enter the account again.": "Le connecteur ne peut pas joindre Visionline avec ce compte. Vérifiez que Visionline fonctionne, puis saisissez à nouveau le compte.",
  "Choose a PNG, JPEG, SVG or WebP logo under 570 KB.": "Choisissez un logo PNG, JPEG, SVG ou WebP de moins de 570 Ko.",
  "Lock diagnosis and battery follow-up: what drains, what to do next, and when to prepare batteries.": "Diagnostic des serrures et suivi des piles : ce qui se décharge, quoi faire ensuite, et quand préparer les piles.",
