  "Nothing yet. Use \"Report a problem\" on the day the batteries drop, an alarm shows or the door does not open, and record the voltage measured at rest and under load.": "Rien pour l'instant. Utilisez « Signaler un problème » le jour où les piles chutent, qu'une alarme apparaît ou que la porte ne s'ouvre pas, et notez la tension mesurée au repos et en charge.",
  "Nothing yet.": "Rien pour l'instant.",
  "Use \"Report a problem\" on the day the batteries drop, an alarm shows or the door does not open, and record the voltage measured at rest and under load.": "Utilisez « Signaler un problème » le jour où les piles chutent, qu'une alarme apparaît ou que la porte ne s'ouvre pas, et notez la tension mesurée au repos et en charge.",
  "Tick everything changed or checked, in the order of the method: cables and alignment first, then the battery holder (rust), the batteries, and only then the LCA and the LCU (swapped with a lock that works).": "Cochez tout ce qui a été changé ou vérifié, dans l'ordre de la méthode : d'abord les câbles et l'alignement, puis le porte-piles (rouille), les piles, et seulement ensuite le LCA et le LCU (échangés avec une serrure qui fonctionne).",
  "Novel locks have everything in one unit: their own parts are shown.": "Les serrures Novel ont tout dans un seul boîtier : leurs propres pièces sont affichées.",
  "Classic Alfa: cables, battery holder, batteries, LCA (lock case adapter), LCU (lock controller unit) and lock case.": "Classic Alfa : câbles, porte-piles, piles, LCA (adaptateur de boîtier de serrure), LCU (unité de contrôle de la serrure) et boîtier de serrure.",
  "Date": "Date",
  "What happened (e.g. batteries dropped, alarm, door did not open)": "Ce qui s'est passé (p. ex. chute des piles, alarme, porte qui ne s'ouvre pas)",
  "Notes (what you saw: rust, cut cable, misalignment, door rubbing…)": "Remarques (ce que vous avez vu : rouille, câble coupé, désalignement, porte qui frotte…)",
  "If the batteries dropped again, read the lock and upload its latest report: if the report shows the drop, change the next part.": "Si les piles ont de nouveau chuté, lisez la serrure et importez son dernier rapport : si le rapport montre la chute, changez la pièce suivante.",
  "Parts changed or checked": "Pièces changées ou vérifiées",
