  "Note a problem on a lock on a given day (the batteries dropped, an alarm, the door did not open), without changing anything.": "Noter un problème sur une serrure un jour donné (chute des piles, alarme, porte qui ne s'ouvre pas), sans rien changer.",
  "Note a problem seen on a day (the batteries dropped, an alarm, the door did not open), or a voltage measured, without changing anything.": "Noter un problème constaté un jour donné (chute des piles, alarme, porte qui ne s'ouvre pas), ou une tension mesurée, sans rien changer.",
